#!/usr/bin/env python3
"""Prepare cf-worker/ with the current server.py and an embedded dataset."""

from __future__ import annotations

import json
import shutil
from pathlib import Path

HERE = Path(__file__).resolve().parent.parent
DEST = HERE / "cf-worker"
raw = (HERE / "dataset.json").read_text(encoding="utf-8")
json.loads(raw)
shutil.copy2(HERE / "server.py", DEST / "server.py")
(DEST / "dataset_embed.py").write_text(
    "# Generated by scripts/embed_dataset.py. Do not edit.\n"
    "from __future__ import annotations\n\n"
    "import json\n\n"
    f"DATA = json.loads({json.dumps(raw)})\n",
    encoding="utf-8",
)
print("prepared cf-worker/server.py and cf-worker/dataset_embed.py", flush=True)
